#include "autogenerated.h"
#include "lcd.h"
#include "tilt_control.h"

extern "C" I2C_HandleTypeDef hi2c2;

#define LCD_I2C_ADDR 0x27

L298N driver1({
        GPIOA, GPIO_PIN_0,
        GPIOA, GPIO_PIN_1
    }, {
        GPIOA, GPIO_PIN_2,
        GPIOA, GPIO_PIN_3
    }
);

L298N driver2({
        GPIOA, GPIO_PIN_8,
        GPIOA, GPIO_PIN_11
    }, {
        GPIOB, GPIO_PIN_0,
        GPIOB, GPIO_PIN_1
    }
);

TiltController tilt_ctrl(driver1, driver2);

void setup() {
    hal_setup();
    lcd_setup(&hi2c2, LCD_I2C_ADDR, LCD_BACKLIGHT_ON | LCD_CURSOR_SHOW | LCD_CURSOR_BLINK);

    tilt_ctrl.init();
    tilt_ctrl.lower_all();
}

int main() {
    setup();

    lcd_set_cursor(0, 0);
    lcd_print("Hello, world!");

    while (1) {
        // logic     
    }
}